class CycleError(Exception):
    pass


def order(deps):
    seen, out = set(), []

    def visit(node):
        if node in seen:
            return
        seen.add(node)
        for dep in deps.get(node, []):
            visit(dep)
        out.append(node)

    for node in deps:
        visit(node)
    return out

