import heapq


class CycleError(Exception):
    pass


def order(deps):
    nodes = set(deps.keys())
    for deps_list in deps.values():
        for d in deps_list:
            nodes.add(d)

    indegree = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}
    for node, deps_list in deps.items():
        for d in deps_list:
            indegree[node] += 1
            dependents[d].append(node)

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    out = []
    while heap:
        node = heapq.heappop(heap)
        out.append(node)
        for m in dependents[node]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)

    if len(out) != len(nodes):
        raise CycleError("dependency cycle detected")
    return out

